node <<'NODE'
const cp = require('child_process');
const path = require('path');
const ts = require('typescript');
const root = process.cwd();
const base = 'a95f28724e7629b524f9f8fdd6aefa8fb0c86fef';
const head = 'a36fd66d803061a63c47089e12d651a5b0b72150';
const git = args => cp.execFileSync('git', args, {encoding: 'utf8'});
const changedOutput = git(['diff', '--name-only', base, head, '--', '*.ts', '*.tsx']).trim();
const changedRel = changedOutput ? changedOutput.split('\n') : [];
const added = new Set(git(['diff', '--diff-filter=A', '--name-only', base, head, '--', '*.ts', '*.tsx']).trim().split('\n').filter(Boolean));
const modified = changedRel.filter(file => !added.has(file));
const baseText = new Map(modified.map(file => [path.resolve(root, file), git(['show', `${base}:${file}`])]));
const configPath = ts.findConfigFile(root, ts.sys.fileExists, 'tsconfig.json');
const config = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(config.config, ts.sys, root);
parsed.options.module = ts.ModuleKind.ESNext;
const host = ts.createCompilerHost(parsed.options);
const originalFileExists = host.fileExists.bind(host);
const originalReadFile = host.readFile.bind(host);
host.fileExists = file => {
  const absolute = path.resolve(file);
  const relative = path.relative(root, absolute);
  if (added.has(relative)) return false;
  if (baseText.has(absolute)) return true;
  return originalFileExists(file);
};
host.readFile = file => {
  const absolute = path.resolve(file);
  if (baseText.has(absolute)) return baseText.get(absolute);
  return originalReadFile(file);
};
host.getSourceFile = (fileName, languageVersion) => {
  const text = host.readFile(fileName);
  return text === undefined ? undefined : ts.createSourceFile(fileName, text, languageVersion, true);
};
const rootNames = [...new Set([...parsed.fileNames.filter(file => !added.has(path.relative(root, file))), ...modified.map(file => path.resolve(root, file))])];
const program = ts.createProgram({rootNames, options: parsed.options, host});
let errors = 0;
let suggestions = 0;
for (const relative of modified) {
  const source = program.getSourceFile(path.resolve(root, relative));
  if (!source) continue;
  for (const diagnostic of [...program.getSyntacticDiagnostics(source), ...program.getSemanticDiagnostics(source)]) {
    errors += 1;
    const start = diagnostic.start == null ? undefined : source.getLineAndCharacterOfPosition(diagnostic.start);
    const location = start ? `${start.line + 1}:${start.character + 1}` : '?:?';
    console.log(`BASE_ERROR ${relative}:${location} TS${diagnostic.code} ${ts.flattenDiagnosticMessageText(diagnostic.messageText, ' ')}`);
  }
  for (const diagnostic of program.getSuggestionDiagnostics(source)) {
    suggestions += 1;
    const start = diagnostic.start == null ? undefined : source.getLineAndCharacterOfPosition(diagnostic.start);
    const location = start ? `${start.line + 1}:${start.character + 1}` : '?:?';
    console.log(`BASE_SUGGESTION ${relative}:${location} TS${diagnostic.code} ${ts.flattenDiagnosticMessageText(diagnostic.messageText, ' ')}`);
  }
}
console.log(`BASE_CHANGED_TS ERRORS ${errors}; SUGGESTIONS ${suggestions}; ADDED_FILES_EXCLUDED ${added.size}`);
